WITH valid_accounts AS (SELECT * FROM accounts WHERE status <> 'CLOSED' OR account_type IN ('CHECKING', 'LOAN')), balance_bucket_summary AS (SELECT CASE WHEN balance >= 83000 THEN 'high' WHEN balance >= 21000 THEN 'mid' ELSE 'low' END AS balance_bucket, ROUND(STDDEV(balance), 2) AS stddev_balance FROM valid_accounts GROUP BY CASE WHEN balance >= 83000 THEN 'high' WHEN balance >= 21000 THEN 'mid' ELSE 'low' END) SELECT balance_bucket, stddev_balance FROM balance_bucket_summary ORDER BY balance_bucket LIMIT 5;
